    "lead": "叶赫是扈伦四部中势力最强的一部, 明廷敕封叶赫贝勒为都督以羁縻制衡建州。万历四十七年 (1619) 萨尔浒战后, 叶赫东城西城俱破, 布寨战死, 布扬古降, 叶赫亡。",
    "parties_note": "叶赫之亡标志着明廷羁縻体系的崩溃。叶赫起源 (蒙古/海西) 之争是 record_vs_scholarship 典型。",
