    "lead": "沈阳是辽东锁钥：洪武二十一年 (1388) 改元沈阳路为沈阳中卫, 一城三衙。天启元年 (1621) 三月袁应泰守沈阳城破自缢, 浑河之战陈策、童仲揆、姜弘立俱殁。后金天命十年 (1625) 自辽阳迁都于此, 改名盛京。",
    "parties_note": "沈阳陷落在明、清、朝鲜三方叙事中各有侧重：明方强调袁应泰决策失误与浑河援军覆没, 清方强调「天祐」与神化努尔哈赤, 朝鲜史料 (尤其《栅中日录》) 提供了最接近现场的视角。",
