    "back": "枢纽",
    "lead": "抚顺是明朝羁縻建州女真的前沿：抚顺关马市是努尔哈赤积累经济与情报的窗口, 也是「七大恨」告天的起点。万历四十六年 (1618) 抚顺陷落, 三年后辽沈尽失。",
    "parties_note": "抚顺之陷标志着明辽东马市羁縻体系的终结。明方强调李永芳降后金的「叛将效应」, 清方将其神化为「天祐」, 学界争论焦点是马市在努尔哈赤崛起中的作用。",
